<script setup lang="ts">
import {ref,computed,onMounted,onBeforeUnmount,watch} from 'vue'
import {matRefresh,matAdd} from '@quasar/extras/material-icons'
import {request} from '../lib/api'
import type {Proxy,Profile,Schedule,CredentialSet,Page} from '../types'
type Kind='proxies'|'profiles'|'schedules'|'credential-sets'
type Resource=Proxy|Profile|Schedule|CredentialSet
const props=defineProps<{kind:Kind}>()
const metadata={proxies:{title:'Proxy profiles',empty:'No proxy profiles',description:'Manage HTTP and HTTPS proxies.'},profiles:{title:'Scan profiles',empty:'No scan profiles',description:'Saved scan configurations.'},schedules:{title:'Schedules',empty:'No schedules',description:'Manage recurring scans.'},'credential-sets':{title:'Credential sets',empty:'No credential sets',description:'Manage saved credential lists.'}}
const meta=computed(()=>metadata[props.kind]),rows=ref<Resource[]>([]),total=ref<number|null>(null),loading=ref(true),error=ref('')
const proxyDialog=ref(false),credentialDialog=ref(false),resourceName=ref(''),proxyURL=ref(''),credentialContent=ref(''),saving=ref(false),formError=ref('')
function clearSecret(){proxyURL.value='';credentialContent.value='';resourceName.value='';formError.value=''}
const editingProxy=ref<Proxy|null>(null),deleting=ref<Resource|null>(null),offset=ref(0),pageSize=ref(10),search=ref(''),notice=ref('')
function openProxy(row?:Proxy){clearSecret();editingProxy.value=row??null;resourceName.value=row?.name??'';proxyDialog.value=true}
function changePage(delta:number){offset.value=Math.max(0,offset.value+delta*pageSize.value);void load()}
function filter(){offset.value=0;void load()}
function findResources(){offset.value=0;void load()}
async function removeResource(){const row=deleting.value;if(!row||saving.value)return;const kind=props.kind;saving.value=true;try{await request(`/${kind}/${row.id}`,{method:'DELETE'});if(props.kind===kind){deleting.value=null;offset.value=0;await load()}}catch(e){if(props.kind===kind)error.value=e instanceof Error?e.message:'Resource could not be removed.'}finally{saving.value=false}}
async function testProxy(row:Proxy){const kind=props.kind;saving.value=true;notice.value='';try{const result=await request<{ok:boolean;message:string}>(`/proxies/${row.id}/test`,{method:'POST'});if(props.kind===kind){notice.value=result.message;await load()}}catch(e){if(props.kind===kind)error.value=e instanceof Error?e.message:'Proxy diagnostic unavailable.'}finally{saving.value=false}}
function openCredentials(){clearSecret();credentialDialog.value=true}
async function saveCredentials(){if(saving.value)return;saving.value=true;formError.value='';try{await request('/credential-sets',{method:'POST',body:{name:resourceName.value.trim(),content:credentialContent.value}});clearSecret();credentialDialog.value=false;await load()}catch(e){formError.value=e instanceof Error?e.message:'The credential set could not be imported.'}finally{saving.value=false}}
function proxyRule(v:unknown){try{const u=new URL(String(v));return (u.protocol==='http:'||u.protocol==='https:')&&!!u.hostname||'Use an HTTP or HTTPS proxy URL.'}catch{return 'Use a complete HTTP or HTTPS proxy URL.'}}
async function saveProxy(){saving.value=true;formError.value='';try{await request(editingProxy.value?`/proxies/${editingProxy.value.id}`:'/proxies',{method:editingProxy.value?'PUT':'POST',body:{name:resourceName.value.trim(),url:proxyURL.value}});clearSecret();proxyDialog.value=false;await load()}catch(e){formError.value=e instanceof Error?e.message:'The proxy could not be saved.'}finally{saving.value=false}}
let controller:AbortController|undefined
async function load(){controller?.abort();controller=new AbortController();const signal=controller.signal;loading.value=true;error.value='';try{const p=await request<Page<Resource>>(`/${props.kind}?`+new URLSearchParams({limit:String(pageSize.value),offset:String(offset.value),search:search.value}),{signal});if(!signal.aborted){rows.value=p.items;total.value=p.total}}catch(e){if(!signal.aborted)error.value=e instanceof Error?e.message:'Could not load saved resources.'}finally{if(!signal.aborted)loading.value=false}}
function detail(row:Resource){switch(props.kind){case 'proxies':{const p=row as Proxy;return `${p.scheme.toUpperCase()} · ${p.host}:${p.port} · ${p.authentication_present?'Authentication configured':'No authentication'}`}case 'profiles':{const p=row as Profile;return p.config.targets.join(', ')}case 'schedules':{const s=row as Schedule;return `${s.enabled?'Enabled':'Paused'} · ${s.cron} · ${s.timezone}`}default:return `${(row as CredentialSet).entry_count} encrypted entries`}}
function date(value:string){return new Date(value).toLocaleString(undefined,{month:'short',day:'numeric',year:'numeric'})}
watch(()=>props.kind,()=>{proxyDialog.value=false;credentialDialog.value=false;clearSecret();deleting.value=null;offset.value=0;search.value='';notice.value='';rows.value=[];total.value=null;void load()});onMounted(load);onBeforeUnmount(()=>{controller?.abort();clearSecret()})
</script>
<template>
 <q-page class="workspace"><header class="page-header"><div><p class="page-kicker">Configuration</p><h1>{{meta.title}}</h1><p class="page-description">{{meta.description}}</p></div><div class="row no-wrap items-center q-gutter-sm"><q-btn flat round :icon="matRefresh" aria-label="Refresh saved resources" :loading="loading" @click="load"/><q-btn v-if="kind==='proxies'" data-testid="add-resource" unelevated color="primary" text-color="dark" :icon="matAdd" label="Add proxy" @click="openProxy()"/><q-btn v-else-if="kind==='credential-sets'" data-testid="add-resource" unelevated color="primary" text-color="dark" :icon="matAdd" label="Import credential set" @click="openCredentials"/><q-btn v-if="kind==='profiles'||kind==='schedules'" :href="`/${kind}/new`" unelevated color="primary" text-color="dark" :label="kind==='profiles'?'New profile':'New schedule'"/></div></header>
  <div v-if="error" class="error-banner" role="alert"><span>{{error}}</span><q-btn flat label="Try again" @click="load"/></div>
  <p v-if="notice" role="status" class="safe-note">{{notice}}</p><div class="row q-gutter-sm q-mb-md"><q-input v-model="search" outlined dense label="Search saved resources" @keyup.enter="findResources"/><q-btn flat label="Search" @click="findResources" :disable="loading"/></div><section class="surface" :aria-busy="loading" :aria-label="meta.title"><div class="section-heading"><h2>Saved configuration</h2><span class="helper">{{total===null?'Not loaded':`${total} total`}}</span></div><div v-if="loading&&!rows.length" role="status" class="loading-label">Loading saved configuration…</div><div v-else-if="!rows.length&&!error" class="resource-empty"><h2>{{meta.empty}}</h2><p>{{props.kind==='proxies'?'Direct HTTP routing remains available. A proxy is optional.':'Nothing has been saved in this workspace yet.'}}</p></div><div v-else class="resource-table-scroll"><table class="resource-table"><thead><tr><th>Name</th><th>Configuration</th><th>Created</th><th>Actions</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td><strong>{{row.name}}</strong></td><td class="resource-description">{{detail(row)}}</td><td>{{date(row.created_at)}}</td><td><div class="row no-wrap"><q-btn v-if="kind==='profiles'||kind==='schedules'" flat label="Edit" :href="`/${kind}/${row.id}/edit`"/><q-btn v-if="kind==='proxies'" flat label="Replace" :data-testid="'edit-'+row.id" @click="openProxy(row as Proxy)"/><q-btn v-if="kind==='proxies'" flat label="Test" :disable="saving" @click="testProxy(row as Proxy)"/><q-btn flat label="Delete" :aria-label="'Delete '+row.name" :data-testid="'delete-'+row.id" @click="deleting=row"/></div></td></tr></tbody></table></div><footer class="compact-pagination" aria-label="Pagination"><label class="page-size-label">Rows <select v-model.number="pageSize" @change="filter" :disabled="loading" aria-label="Rows per page"><option :value="10">10</option><option :value="25">25</option><option :value="50">50</option></select></label><span>{{total===null?'Loading…':`${total?offset+1:0}–${Math.min(offset+pageSize,total)} of ${total}`}}</span><div><q-btn flat dense label="Previous" :disable="loading||offset===0" @click="offset=Math.max(0,offset-pageSize);load()"/><q-btn flat dense label="Next" :disable="loading||total===null||offset+pageSize>=total" @click="offset+=pageSize;load()"/></div></footer></section>


  <q-dialog v-model="proxyDialog" @hide="clearSecret"><q-card class="resource-dialog"><q-form autocomplete="off" @submit="saveProxy"><q-card-section><span class="section-label">HTTP routing</span><h2>{{editingProxy?'Replace proxy configuration':'Add a proxy profile'}}</h2><p v-if="editingProxy" class="safe-note">Enter the replacement proxy URL.</p><p class="helper">Saved authentication is hidden.</p><div v-if="formError" role="alert" class="error-banner">{{formError}}</div><q-input v-model="resourceName" name="resource_name" outlined label="Profile name" maxlength="200" autocomplete="off" :rules="[v=>!!String(v).trim()||'Name this proxy.']"/><q-input v-model="proxyURL" class="q-mt-md" name="proxy_url" type="password" outlined label="Full HTTP / HTTPS proxy URL" placeholder="http://proxy.example:8080" autocomplete="new-password" spellcheck="false" :rules="[proxyRule]" hint="Include authentication in the URL if required. SOCKS proxies are not supported by this HTTP transport."/><p class="safe-note q-mt-lg">HTTP/HTTPS traffic only.</p></q-card-section><q-card-actions align="right"><q-btn flat label="Cancel" :disable="saving" v-close-popup/><q-btn unelevated type="submit" color="primary" text-color="dark" label="Save proxy" :loading="saving"/></q-card-actions></q-form></q-card></q-dialog>
  <q-dialog v-model="credentialDialog" @hide="clearSecret"><q-card class="resource-dialog"><q-form autocomplete="off" @submit="saveCredentials"><q-card-section><span class="section-label">Write-only import</span><h2>Import a credential set</h2><p class="helper">Paste a credential list to save it.</p><div v-if="formError" role="alert" class="error-banner">{{formError}}</div><q-input v-model="resourceName" name="resource_name" outlined label="Set name" maxlength="200" autocomplete="off" :rules="[v=>!!String(v).trim()||'Name this credential set.']"/><q-input v-model="credentialContent" class="q-mt-md" name="credential_content" type="textarea" rows="6" outlined label="One username:password pair per line" autocomplete="off" spellcheck="false" maxlength="750000" :rules="[v=>!!String(v).trim()||'Paste the authorized entries.']" hint="Visible only while this dialog is open. An empty password is represented by a trailing colon."/><p class="safe-note q-mt-lg"></p></q-card-section><q-card-actions align="right"><q-btn flat label="Cancel" :disable="saving" v-close-popup/><q-btn unelevated type="submit" color="primary" text-color="dark" label="Import encrypted set" :loading="saving"/></q-card-actions></q-form></q-card></q-dialog>
<q-dialog :model-value="!!deleting" @update:model-value="v=>{if(!v&&!saving)deleting=null}"><q-card class="resource-dialog"><q-card-section><h2>Delete {{deleting?.name}}?</h2><p>Remove this resource from future selections. Existing job snapshots are not changed.</p></q-card-section><q-card-actions align="right"><q-btn flat label="Keep resource" :disable="saving" @click="deleting=null"/><q-btn flat color="negative" label="Delete saved resource" :loading="saving" @click="removeResource"/></q-card-actions></q-card></q-dialog> </q-page>
</template>
<style scoped>.resource-description{max-width:480px;overflow-wrap:anywhere}.resource-table td{vertical-align:top}.resource-table td:first-child{min-width:140px}.resource-table td:last-child{white-space:nowrap;font-size:11px;color:var(--muted)}.section-heading h2{font-size:18px;margin:0}.resource-dialog{width:540px;max-width:calc(100vw - 28px);padding:12px}.resource-dialog h2{margin-top:18px;margin-bottom:15px}.resource-dialog .q-card__actions{padding:12px 16px}</style>
